questionvariables.text:
/************** You can find latest version in github/yositomi-opu/stack_question ***********/
stack_include("https://yositomi-opu.github.io/stack_questions/ky_linear_algebra.mac");
/* The difference of -cb and -rb is only type of ans1(checkbox or radio button) and this setting */
%__mcq_rb_cb:"rb";
/*************** some usual fuctions I use. Feel free to customize here **********************/
powerdisp:true;
%_rp(L):=random_permutation(L);
stack_include("https://yositomi-opu.github.io/stack_questions/tex_library.mac");
/*********************************** Flags ***********************************/
/* NOTE: opts=options, copts=correct options, wopts=wrong(incorrect) options */

/* Flags : modification not required if not necessary. See mcq_template_pre_cas.txt for details */
/* [use feedback?, use subscore?, use noidea opt, use nocorrect opt, is nocorrect opt true?, use qtext_auto?] */

%_MCQ_FLAGS:[true, true, false, false, rand([true, false]), true];

/* NOTE: If the number of correct/incorrect answer patterns exceeds 5/9, increase the number of PRT nodes */
/*       and adjust the following constants. */
%__mcq_max_cp:5;
%__mcq_max_wp:9;

/********************************* DO NOT EDIT HERE **************************************/
stack_include("https://yositomi-opu.github.io/stack_questions/mcq_template_pre_cas.mac");
/*****************************************************************************************/
/* MCQ_WEBAPP_DATA_BASE64: */

/******************************** MAIN QUESTION VARIABLES ********************************/


%_MCQ_NUM_OPTS:7;
%_MCQ_NUM_COPTS:1;
%__mcq_nocorrectopt:false;
%__mcq_noidea:false;
%__mcq_scmethod:1;
/***** See the Sample.txt file below for how to describe question variables here *********/
/* c[1], w[4, 4] */
stack_include("https://yositomi-opu.github.io/stack_questions/001/GaussElimCoeffMat-A.txt");

/***************************** END OF MAIN QUESTION VARIABLES ****************************/

/*********************************** DO NOT EDIT HERE ************************************/
/*************** patterns is automatically generate by the post template *****************/
stack_include("https://yositomi-opu.github.io/stack_questions/mcq_template_post_cas.mac");
/*****************************************************************************************/

%__mcq_langcode:castext("[[lang code=\"en\"]][[/lang]][[lang code=\"ja\"]][[/lang]][[lang code=\"fr\"]][[/lang]][[lang code=\"it\"]][[/lang]][[lang code=\"de\"]][[/lang]][[lang code=\"pt\"]][[/lang]][[lang code=\"zh\"]][[/lang]][[lang code=\"ko\"]][[/lang]][[lang code=\"ru\"]][[/lang]][[lang code=\"sv\"]][[/lang]][[lang code=\"es\"]][[/lang]]");
